function WINDING_NUMBER(theta, samples):
    total <- 0 ; prev <- theta(0)
    for k = 1..samples:
        cur <- theta(k / samples)
        d <- cur - prev
        unwrap d into (-pi, pi]
        total <- total + d ; prev <- cur
    return round(total / (2*pi))
